CREATE SCHEMA IF NOT EXISTS risk;
COMMENT ON SCHEMA risk IS 'Fraud detection, explainable trust scores, challenges and human risk operations';

CREATE TABLE risk.rule_sets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),key varchar(80) NOT NULL,version integer NOT NULL CHECK(version>0),rules jsonb NOT NULL CHECK(jsonb_typeof(rules)='array'),state text NOT NULL DEFAULT 'draft' CHECK(state IN('draft','published','retired')),created_by uuid NOT NULL,approved_by uuid,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),published_at timestamptz,CHECK(approved_by IS NULL OR approved_by<>created_by),UNIQUE(tenant_id,key,version));
CREATE INDEX risk_rule_set_lookup_idx ON risk.rule_sets(tenant_id,key,state,version DESC);

CREATE TABLE risk.model_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),model_key varchar(80) NOT NULL,version varchar(80) NOT NULL,checksum char(64) NOT NULL CHECK(checksum~'^[a-f0-9]{64}$'),features jsonb NOT NULL CHECK(jsonb_typeof(features)='array'),thresholds jsonb NOT NULL CHECK(jsonb_typeof(thresholds)='object'),state text NOT NULL DEFAULT 'shadow' CHECK(state IN('shadow','active','retired')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),activated_at timestamptz,UNIQUE(tenant_id,model_key,version));

CREATE TABLE risk.signals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),subject_type text NOT NULL CHECK(subject_type IN('user','business','listing','payment','session')),subject_id uuid NOT NULL,code varchar(80) NOT NULL,source text NOT NULL CHECK(source IN('rule','velocity','device','graph','model','watchlist')),score integer NOT NULL CHECK(score BETWEEN 0 AND 1000),explanation varchar(240) NOT NULL,evidence_hash char(64) NOT NULL CHECK(evidence_hash~'^[a-f0-9]{64}$'),occurred_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz,idempotency_key varchar(160) NOT NULL,UNIQUE(tenant_id,idempotency_key));
CREATE INDEX risk_signal_subject_idx ON risk.signals(tenant_id,subject_type,subject_id,occurred_at DESC);
CREATE INDEX risk_signal_code_idx ON risk.signals(tenant_id,code,occurred_at DESC);

CREATE TABLE risk.device_fingerprints(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),fingerprint_hash char(64) NOT NULL CHECK(fingerprint_hash~'^[a-f0-9]{64}$'),first_seen_at timestamptz NOT NULL,last_seen_at timestamptz NOT NULL,account_count integer NOT NULL DEFAULT 1 CHECK(account_count>=0),risk_score integer NOT NULL DEFAULT 0 CHECK(risk_score BETWEEN 0 AND 1000),state text NOT NULL DEFAULT 'active' CHECK(state IN('active','challenged','blocked','expired')),UNIQUE(tenant_id,fingerprint_hash));
CREATE INDEX risk_device_score_idx ON risk.device_fingerprints(tenant_id,risk_score DESC,last_seen_at DESC);

CREATE TABLE risk.account_edges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),left_subject_id uuid NOT NULL,right_subject_id uuid NOT NULL,edge_type text NOT NULL CHECK(edge_type IN('shared_device','shared_payment','shared_contact','shared_network','reported_relation')),weight integer NOT NULL CHECK(weight BETWEEN 1 AND 1000),evidence_hash char(64) NOT NULL CHECK(evidence_hash~'^[a-f0-9]{64}$'),first_seen_at timestamptz NOT NULL,last_seen_at timestamptz NOT NULL,CHECK(left_subject_id<>right_subject_id),UNIQUE(tenant_id,left_subject_id,right_subject_id,edge_type));
CREATE INDEX risk_edge_left_idx ON risk.account_edges(tenant_id,left_subject_id,weight DESC);
CREATE INDEX risk_edge_right_idx ON risk.account_edges(tenant_id,right_subject_id,weight DESC);

CREATE TABLE risk.profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),subject_type text NOT NULL CHECK(subject_type IN('user','business')),subject_id uuid NOT NULL,trust_score integer NOT NULL DEFAULT 500 CHECK(trust_score BETWEEN 0 AND 1000),trust_band text NOT NULL DEFAULT 'standard' CHECK(trust_band IN('trusted','established','standard','restricted')),risk_score integer NOT NULL DEFAULT 0 CHECK(risk_score BETWEEN 0 AND 1000),positive_factors jsonb NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(positive_factors)='array'),negative_factors jsonb NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(negative_factors)='array'),version integer NOT NULL DEFAULT 1 CHECK(version>0),evaluated_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,subject_type,subject_id));
CREATE INDEX risk_profile_score_idx ON risk.profiles(tenant_id,risk_score DESC,trust_score);

CREATE TABLE risk.evaluations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),subject_type text NOT NULL CHECK(subject_type IN('user','business','listing','payment','session')),subject_id uuid NOT NULL,rule_set_id uuid REFERENCES risk.rule_sets(id) ON DELETE RESTRICT,model_version_id uuid REFERENCES risk.model_versions(id) ON DELETE RESTRICT,risk_score integer NOT NULL CHECK(risk_score BETWEEN 0 AND 1000),action text NOT NULL CHECK(action IN('allow','review','challenge','block')),reason_codes jsonb NOT NULL CHECK(jsonb_typeof(reason_codes)='array'),signal_summary jsonb NOT NULL CHECK(jsonb_typeof(signal_summary)='array'),graph_score integer NOT NULL DEFAULT 0 CHECK(graph_score BETWEEN 0 AND 1000),idempotency_key varchar(160) NOT NULL,evaluated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,idempotency_key));
CREATE INDEX risk_evaluation_subject_idx ON risk.evaluations(tenant_id,subject_type,subject_id,evaluated_at DESC);
CREATE INDEX risk_evaluation_action_idx ON risk.evaluations(tenant_id,action,risk_score DESC,evaluated_at DESC);

CREATE TABLE risk.cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),evaluation_id uuid NOT NULL REFERENCES risk.evaluations(id) ON DELETE RESTRICT,subject_type text NOT NULL CHECK(subject_type IN('user','business','listing','payment','session')),subject_id uuid NOT NULL,state text NOT NULL DEFAULT 'open' CHECK(state IN('open','claimed','escalated','resolved','cancelled')),priority integer NOT NULL CHECK(priority BETWEEN 0 AND 1000),sla_due_at timestamptz NOT NULL,claimed_by uuid,claimed_at timestamptz,lease_expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,evaluation_id));
CREATE INDEX risk_case_queue_idx ON risk.cases(tenant_id,state,priority DESC,sla_due_at) WHERE state IN('open','claimed','escalated');

CREATE TABLE risk.decisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),case_id uuid NOT NULL REFERENCES risk.cases(id) ON DELETE RESTRICT,actor_id uuid NOT NULL,approver_id uuid,action text NOT NULL CHECK(action IN('allow','review','challenge','block')),reason varchar(500) NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(action<>'block' OR(approver_id IS NOT NULL AND approver_id<>actor_id)));
CREATE INDEX risk_decision_case_idx ON risk.decisions(tenant_id,case_id,created_at DESC);

CREATE TABLE risk.case_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),case_id uuid NOT NULL REFERENCES risk.cases(id) ON DELETE RESTRICT,event_type varchar(80) NOT NULL,actor_id uuid,payload jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(payload)='object'),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX risk_case_event_idx ON risk.case_events(tenant_id,case_id,created_at);

CREATE TABLE risk.challenges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),evaluation_id uuid NOT NULL REFERENCES risk.evaluations(id) ON DELETE RESTRICT,subject_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('otp','identity','payment_3ds','document','manual_review')),state text NOT NULL DEFAULT 'pending' CHECK(state IN('pending','passed','failed','expired','cancelled')),attempts integer NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 10),expires_at timestamptz NOT NULL,completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,evaluation_id,kind));
CREATE INDEX risk_challenge_subject_idx ON risk.challenges(tenant_id,subject_id,state,expires_at);

CREATE TABLE risk.watchlist_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),subject_hash char(64) NOT NULL CHECK(subject_hash~'^[a-f0-9]{64}$'),kind text NOT NULL CHECK(kind IN('device','payment','contact','network','identity')),reason_code varchar(80) NOT NULL,severity integer NOT NULL CHECK(severity BETWEEN 1 AND 1000),state text NOT NULL DEFAULT 'active' CHECK(state IN('active','expired','revoked')),created_by uuid NOT NULL,approved_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz,CHECK(created_by<>approved_by),UNIQUE(tenant_id,subject_hash,kind));
CREATE INDEX risk_watchlist_lookup_idx ON risk.watchlist_entries(tenant_id,subject_hash,state);

CREATE TABLE risk.daily_metrics(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),metric_date date NOT NULL,open_cases integer NOT NULL DEFAULT 0 CHECK(open_cases>=0),challenged_today integer NOT NULL DEFAULT 0 CHECK(challenged_today>=0),blocked_today integer NOT NULL DEFAULT 0 CHECK(blocked_today>=0),average_risk_score integer NOT NULL DEFAULT 0 CHECK(average_risk_score BETWEEN 0 AND 1000),false_positive_bps integer NOT NULL DEFAULT 0 CHECK(false_positive_bps BETWEEN 0 AND 10000),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,metric_date));

CREATE FUNCTION risk.reject_immutable_mutation() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'risk_evidence_append_only';END$$;
CREATE TRIGGER risk_signals_immutable BEFORE UPDATE OR DELETE ON risk.signals FOR EACH ROW EXECUTE FUNCTION risk.reject_immutable_mutation();
CREATE TRIGGER risk_evaluations_immutable BEFORE UPDATE OR DELETE ON risk.evaluations FOR EACH ROW EXECUTE FUNCTION risk.reject_immutable_mutation();
CREATE TRIGGER risk_decisions_immutable BEFORE UPDATE OR DELETE ON risk.decisions FOR EACH ROW EXECUTE FUNCTION risk.reject_immutable_mutation();
CREATE TRIGGER risk_case_events_immutable BEFORE UPDATE OR DELETE ON risk.case_events FOR EACH ROW EXECUTE FUNCTION risk.reject_immutable_mutation();

DO $$DECLARE table_name text;BEGIN FOREACH table_name IN ARRAY ARRAY['rule_sets','model_versions','signals','device_fingerprints','account_edges','profiles','evaluations','cases','decisions','case_events','challenges','watchlist_entries','daily_metrics'] LOOP EXECUTE format('ALTER TABLE risk.%I ENABLE ROW LEVEL SECURITY',table_name);EXECUTE format('ALTER TABLE risk.%I FORCE ROW LEVEL SECURITY',table_name);EXECUTE format('CREATE POLICY %I ON risk.%I USING(tenant_id=NULLIF(current_setting(''app.current_tenant_id'',true),'''')::uuid) WITH CHECK(tenant_id=NULLIF(current_setting(''app.current_tenant_id'',true),'''')::uuid)',table_name||'_tenant_isolation',table_name);END LOOP;END$$;
